-- Default off: no activation row is inserted by migration.
CREATE TABLE IF NOT EXISTS continuous_undo_serialization_activation(singleton INTEGER PRIMARY KEY CHECK(singleton=1),activated_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS continuous_undo_activation_no_update BEFORE UPDATE ON continuous_undo_serialization_activation BEGIN SELECT RAISE(ABORT,'undo serialization activation immutable'); END;
CREATE TRIGGER IF NOT EXISTS continuous_undo_activation_no_delete BEFORE DELETE ON continuous_undo_serialization_activation BEGIN SELECT RAISE(ABORT,'undo serialization activation retained'); END;
CREATE TRIGGER IF NOT EXISTS continuous_undo_activation_no_replace BEFORE INSERT ON continuous_undo_serialization_activation WHEN EXISTS(SELECT 1 FROM continuous_undo_serialization_activation WHERE singleton=NEW.singleton) BEGIN SELECT RAISE(ABORT,'undo serialization activation collision'); END;
CREATE TABLE IF NOT EXISTS continuous_pending_undo(
 request_id TEXT PRIMARY KEY,
 expense_id TEXT NOT NULL,
 source_version INTEGER NOT NULL CHECK(source_version>0),
 publication_transition_id TEXT NOT NULL REFERENCES continuous_publication_intents(transition_id),
 line_user_id TEXT NOT NULL,
 trace_id TEXT NOT NULL,
 actor_employee_id TEXT,
 branch_id TEXT,
 state TEXT NOT NULL CHECK(state IN ('PENDING','APPLIED')),
 audit_id TEXT,
 cancelled_version INTEGER,
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL,
 UNIQUE(expense_id,source_version),
 CHECK((state='PENDING' AND audit_id IS NULL AND cancelled_version IS NULL) OR (state='APPLIED' AND audit_id IS NOT NULL AND cancelled_version>source_version))
);
CREATE TRIGGER IF NOT EXISTS continuous_pending_undo_insert BEFORE INSERT ON continuous_pending_undo
WHEN NEW.state<>'PENDING' OR NOT EXISTS(SELECT 1 FROM continuous_undo_serialization_activation WHERE singleton=1) OR NOT EXISTS(SELECT 1 FROM expense_events e JOIN continuous_publication_intents i ON i.transition_id=NEW.publication_transition_id AND i.entity_id=e.expense_id AND i.source_version=e.version AND i.kind='PUBLISH' LEFT JOIN stable_workbook_claims c ON c.spreadsheet_id=i.spreadsheet_id AND c.operation_token=i.claim_token WHERE e.expense_id=NEW.expense_id AND e.version=NEW.source_version AND e.line_user_id=NEW.line_user_id AND e.status='CONFIRMED' AND (i.state IN ('IN_FLIGHT','REVIEW') OR (i.state='VERIFIED' AND c.state IN ('HELD','REVIEW'))))
BEGIN SELECT RAISE(ABORT,'pending undo requires confirmed owner'); END;
CREATE TRIGGER IF NOT EXISTS continuous_pending_undo_transition BEFORE UPDATE ON continuous_pending_undo
WHEN NEW.request_id IS NOT OLD.request_id OR NEW.expense_id IS NOT OLD.expense_id OR NEW.source_version IS NOT OLD.source_version OR NEW.publication_transition_id IS NOT OLD.publication_transition_id OR NEW.line_user_id IS NOT OLD.line_user_id OR NEW.trace_id IS NOT OLD.trace_id OR NEW.actor_employee_id IS NOT OLD.actor_employee_id OR NEW.branch_id IS NOT OLD.branch_id OR NEW.created_at IS NOT OLD.created_at OR OLD.state<>'PENDING' OR NEW.state<>'APPLIED' OR NOT EXISTS(SELECT 1 FROM expense_events e JOIN expense_audit_log a ON a.expense_id=e.expense_id AND a.audit_id=NEW.audit_id AND a.action='UNDO' WHERE e.expense_id=NEW.expense_id AND e.status='CANCELLED' AND e.version=NEW.cancelled_version AND json_extract(a.before_json,'$.version')=OLD.source_version AND json_extract(a.after_json,'$.version')=NEW.cancelled_version AND EXISTS(SELECT 1 FROM sync_jobs j WHERE j.entity_type='EXPENSE' AND j.entity_key=e.expense_id AND j.entity_version=e.version))
BEGIN SELECT RAISE(ABORT,'pending undo transition unverified'); END;
CREATE TRIGGER IF NOT EXISTS continuous_pending_undo_no_delete BEFORE DELETE ON continuous_pending_undo BEGIN SELECT RAISE(ABORT,'pending undo retained'); END;
CREATE TRIGGER IF NOT EXISTS continuous_pending_undo_no_replace BEFORE INSERT ON continuous_pending_undo WHEN EXISTS(SELECT 1 FROM continuous_pending_undo WHERE request_id=NEW.request_id OR (expense_id=NEW.expense_id AND source_version=NEW.source_version)) BEGIN SELECT RAISE(ABORT,'pending undo collision'); END;
CREATE TRIGGER IF NOT EXISTS continuous_pending_undo_blocks_publish BEFORE INSERT ON continuous_publication_intents WHEN NEW.kind='PUBLISH' AND EXISTS(SELECT 1 FROM continuous_undo_serialization_activation WHERE singleton=1) AND EXISTS(SELECT 1 FROM continuous_pending_undo u WHERE u.expense_id=NEW.entity_id AND u.source_version=NEW.source_version AND u.state='PENDING') BEGIN SELECT RAISE(ABORT,'pending undo prevents publication'); END;
CREATE TRIGGER IF NOT EXISTS continuous_undo_guard_expense_update BEFORE UPDATE ON expense_events WHEN EXISTS(SELECT 1 FROM continuous_undo_serialization_activation a JOIN continuous_publication_intents i ON i.entity_id=OLD.expense_id AND i.kind='PUBLISH' LEFT JOIN stable_workbook_claims c ON c.spreadsheet_id=i.spreadsheet_id AND c.operation_token=i.claim_token WHERE a.singleton=1 AND (i.state IN ('IN_FLIGHT','REVIEW') OR (i.state='VERIFIED' AND c.state IN ('HELD','REVIEW')))) BEGIN SELECT RAISE(ABORT,'publication source is resolving'); END;
CREATE TRIGGER IF NOT EXISTS continuous_undo_guard_expense_delete BEFORE DELETE ON expense_events WHEN EXISTS(SELECT 1 FROM continuous_undo_serialization_activation a JOIN continuous_publication_intents i ON i.entity_id=OLD.expense_id AND i.kind='PUBLISH' LEFT JOIN stable_workbook_claims c ON c.spreadsheet_id=i.spreadsheet_id AND c.operation_token=i.claim_token WHERE a.singleton=1 AND (i.state IN ('IN_FLIGHT','REVIEW') OR (i.state='VERIFIED' AND c.state IN ('HELD','REVIEW')))) BEGIN SELECT RAISE(ABORT,'publication source is resolving'); END;
